package com.dpworld.fms.api;
import com.dpworld.fms.routing.PlannedRouteRepository;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;
@Repository public class PostgresPlannedRouteRepository implements PlannedRouteRepository{private final JdbcTemplate jdbc;public PostgresPlannedRouteRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}@Transactional public UUID save(PlannedRoute route){jdbc.update("INSERT INTO routes(id,job_id,graph_version,graph_version_id,total_distance_m,estimated_seconds,created_at,source_node_code,destination_node_code,route_geojson,failure_reason) VALUES (?,?,?,?,?,?,?,?,?,?::jsonb,?)",route.id(),route.jobId(),route.graphVersion(),route.graphId(),route.distanceMetres(),route.travelSeconds(),Timestamp.from(route.createdAt()),route.sourceNode(),route.destinationNode(),route.geoJson(),route.failureReason());for(int i=0;i<route.orderedSegmentIds().size();i++)jdbc.update("INSERT INTO route_segments(route_id,sequence_no,road_segment_id) VALUES (?,?,?)",route.id(),i,UUID.fromString(route.orderedSegmentIds().get(i)));return route.id();}public Optional<PlannedRoute>find(UUID id){List<Map<String,Object>>rows=jdbc.queryForList("SELECT * FROM routes WHERE id=?",id);if(rows.isEmpty())return Optional.empty();Map<String,Object>r=rows.getFirst();List<String>segments=jdbc.queryForList("SELECT road_segment_id::text FROM route_segments WHERE route_id=? ORDER BY sequence_no",String.class,id);return Optional.of(new PlannedRoute(id,(UUID)r.get("job_id"),(UUID)r.get("graph_version_id"),((Number)r.get("graph_version")).longValue(),String.valueOf(r.get("source_node_code")),String.valueOf(r.get("destination_node_code")),((Number)r.get("total_distance_m")).doubleValue(),((Number)r.get("estimated_seconds")).doubleValue(),segments,String.valueOf(r.get("route_geojson")),String.valueOf(r.get("failure_reason")),((Timestamp)r.get("created_at")).toInstant()));}}
